    "sosGuiaGases": {"es": "Hay gases volcánicos", "en": "There are volcanic gases", "fr": "Il y a des gaz volcaniques", "de": "Vulkanische Gase", "it": "Ci sono gas vulcanici", "nl": "Vulkanische gassen", "zh": "出现火山气体", "zht": "出現火山氣體", "bg": "Има вулканични газове", "pl": "Są gazy wulkaniczne"},
    "sosGuiaSismo": {"es": "Tiembla la tierra", "en": "The ground shakes", "fr": "La terre tremble", "de": "Erdbeben", "it": "La terra trema", "nl": "Aardbeving", "zh": "发生地震", "zht": "發生地震", "bg": "Земята се тресе", "pl": "Trzęsie się ziemia"},
