      return a && typeof a.titulo === 'string' && a.titulo.length > 4 && a.titulo.length < 300 && !isNaN(Date.parse(a.t)) &&
             typeof a.enlace === 'string' && /^https:\/\/www3\.gobiernodecanarias\.org\/noticias\//.test(a.enlace);
